  "implementation": "def solve(case):
    nodes = case['payload']['nodes']
    required_symbols = set(case['payload']['required_symbols'])
    node_map = {}
    for n in nodes:
        nid = n['id']
        node_map[nid] = {
            'id': nid,
            'parent': n['parent'],
            'symbol': n['symbol'],
            'depth': n['depth'],
            'removable': n['removable'],
            'children': set()
        }
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            node_map[pid]['children'].add(n['id'])
    retained = set(node_map.keys())
    removal_order = []
    while True:
        candidates = []
        for nid, info in node_map.items():
            if nid not in retained:
                continue
            if not info['removable']:
                continue
            if info['symbol'] in required_symbols:
                continue
            if info['parent'] is None:
                continue
            if len(info['children']) > 0:
                continue
            candidates.append(info)
        if not candidates:
            break
        candidates.sort(key=lambda x: (-x['depth'], x['id']))
        removed = False
        for cand in candidates:
            nid = cand['id']
            pid = cand['parent']
            if nid not in retained:
                continue
            parent = node_map[pid]
            parent['children'].discard(nid)
            retained.discard(nid)
            removal_order.append(nid)
            removed = True
            break
        if not removed:
            break
    result = {
        'retained_ids': sorted(retained),
        'removal_order': removal_order
    }
    return result"
